		return {
			kind: { _tag: "FileWrite", path: path ?? url ?? tool },
			category: "edit",
		};
	}
	const reads = [
		"fetch",
		"find",
		"get",
		"glob",
		"grep",
		"inspect",
		"list",
		"read",
		"search",
		"stat",
		"view",
		"web",
